import {
  DeviceModel,
  DeviceType,
  NetworkLink,
  NetworkNode,
  ServerServices,
  TopologyData,
} from './types';
import { generateMacAddress } from './ipMath';
import { getDefaultFirewallConfig } from './firewallEngine';
import {
  getDefaultIpCameraConfig,
  getDefaultSwitchPoeConfig,
  getDefaultVoipPhoneConfig,
} from './poeAndVoipEngine';
import {
  getDefaultBgpConfig,
  getDefaultWanImpairmentConfig,
} from './bgpAndWanEngine';
import {
  generateDefaultGponSn,
  getDefaultGponOltConfig,
  getDefaultGponOntConfig,
} from './gponEngine';
import { syncConnectedRoutes } from './simulator';

export function createDefaultServices(type: DeviceType): ServerServices {
  return {
    dhcpEnabled: type === 'router' || type === 'server',
    dhcpPools: [],
    dhcpLeases: [],
    dnsEnabled: type === 'server',
    dnsRecords: [
      { id: 'dns-1', domain: 'app.corp.local', ipAddress: '192.168.2.100' },
      { id: 'dns-2', domain: 'portal.netpulse.lan', ipAddress: '192.168.2.100' },
      { id: 'dns-3', domain: 'gateway.corp.local', ipAddress: '192.168.1.1' },
    ],
    httpEnabled: type === 'server',
    httpTitle: 'NetPulse Corporate Intranet Portal (HTTP/1.1 200 OK)',
    httpBody:
      'Добро пожаловать на веб-сервер SRV-Web! DNS-разрешение имени, TCP 3-Way Handshake (SYN / SYN-ACK / ACK) и передача HTTP GET успешно выполнены.',
  };
}

export function createDeviceNode(
  type: DeviceType,
  index: number,
  x: number,
  y: number,
  customName?: string,
  switchPortCount: number = 6,
  deviceModel?: DeviceModel
): NetworkNode {
  const effectiveModel: DeviceModel = deviceModel || type;
  const cleanSwitchPorts = type === 'switch' ? Math.max(2, switchPortCount) : 6;
  const prefix =
    effectiveModel === 'firewall'
      ? 'FW-ASA'
      : effectiveModel === 'wlc'
      ? 'WLC'
      : effectiveModel === 'wifi_ap'
      ? 'AP'
      : effectiveModel === 'soho_wifi_router'
      ? 'WiFi-RTR'
      : effectiveModel === 'laptop'
      ? 'Laptop'
      : effectiveModel === 'smartphone'
      ? 'Phone'
      : effectiveModel === 'ip_phone'
      ? 'IP-Phone'
      : effectiveModel === 'ip_camera'
      ? 'CAM'
      : effectiveModel === 'nvr'
      ? 'NVR'
      : effectiveModel === 'isp_cloud'
      ? 'ISP-WAN'
      : effectiveModel === 'gpon_olt'
      ? 'OLT-GPON'
      : effectiveModel === 'gpon_ont'
      ? 'ONT'
      : type === 'router'
      ? 'RTR'
      : type === 'switch'
      ? cleanSwitchPorts >= 24
        ? 'SW24'
        : 'SW'
      : type === 'server'
      ? 'SRV'
      : 'PC';
  const name =
    customName ||
    (effectiveModel === 'ip_phone'
      ? `IP-Phone-${100 + index}`
      : effectiveModel === 'ip_camera'
      ? `CAM-${String(index).padStart(2, '0')}`
      : effectiveModel === 'nvr'
      ? `NVR-Recorder-${index}`
      : effectiveModel === 'isp_cloud'
      ? `ISP-Cloud-AS${65100 + index}`
      : effectiveModel === 'gpon_olt'
      ? `OLT-GPON-${index}`
      : effectiveModel === 'gpon_ont'
      ? `ONT-Home-${index}`
      : `${prefix}-${index}`);
  const id = `${effectiveModel}-${Date.now()}-${index}`;

  const interfaces =
    effectiveModel === 'firewall'
      ? [
          {
            id: `${id}-gi0/0`,
            name: 'GigabitEthernet0/0 (Inside · Level 100)',
            shortName: 'Gi0/0',
            macAddress: generateMacAddress(index + 80, 1),
            ipAddress: '192.168.100.1',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            natRole: 'inside' as const,
            securityZone: 'inside' as const,
            securityLevel: 100,
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-gi0/1`,
            name: 'GigabitEthernet0/1 (DMZ · Level 50)',
            shortName: 'Gi0/1',
            macAddress: generateMacAddress(index + 80, 2),
            ipAddress: '172.16.50.1',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            natRole: 'inside' as const,
            securityZone: 'dmz' as const,
            securityLevel: 50,
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-gi0/2`,
            name: 'GigabitEthernet0/2 (Outside · Level 0)',
            shortName: 'Gi0/2',
            macAddress: generateMacAddress(index + 80, 3),
            ipAddress: '203.0.113.2',
            subnetMask: '255.255.255.252',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            natRole: 'outside' as const,
            securityZone: 'outside' as const,
            securityLevel: 0,
            bandwidthMbps: 1000,
          },
        ]
      : effectiveModel === 'wlc'
      ? Array.from({ length: 4 }, (_, i) => {
          const portNum = i + 1;
          return {
            id: `${id}-gi0/${portNum}`,
            name: `GigabitEthernet0/${portNum} (WLC Distribution Trunk)`,
            shortName: `Gi0/${portNum}`,
            macAddress: generateMacAddress(index + 70, portNum),
            ipAddress: portNum === 1 ? '192.168.10.5' : '',
            subnetMask: portNum === 1 ? '255.255.255.0' : '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 10,
            trunkAllowedVlans: [1, 10, 20, 30],
            bandwidthMbps: 1000,
          };
        })
      : effectiveModel === 'wifi_ap'
      ? [
          {
            id: `${id}-gi0/1`,
            name: 'GigabitEthernet0/1 (Uplink)',
            shortName: 'Gi0/1',
            macAddress: generateMacAddress(index + 40, 1),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            bandwidthMbps: 1000,
          },
          ...Array.from({ length: 6 }, (_, i) => {
            const slot = i + 1;
            return {
              id: `${id}-wlan0/${slot}`,
              name: `Dot11Radio0/${slot}`,
              shortName: `Wlan0/${slot}`,
              macAddress: generateMacAddress(index + 40, slot + 1),
              ipAddress: '',
              subnetMask: '',
              adminStatus: 'up' as const,
              vlanMode: 'access' as const,
              accessVlan: 1,
              trunkAllowedVlans: [1, 10, 20, 30],
              isWireless: true,
              bandwidthMbps: 300,
            };
          }),
        ]
      : effectiveModel === 'soho_wifi_router'
      ? [
          {
            id: `${id}-gi0/0`,
            name: 'GigabitEthernet0/0 (WAN)',
            shortName: 'Gi0/0',
            macAddress: generateMacAddress(index + 50, 1),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            natRole: 'outside' as const,
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-fa0/0`,
            name: 'FastEthernet0/0 (LAN)',
            shortName: 'Fa0/0',
            macAddress: generateMacAddress(index + 50, 2),
            ipAddress: '192.168.1.1',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            natRole: 'inside' as const,
            bandwidthMbps: 100,
          },
          {
            id: `${id}-wlan0`,
            name: 'Dot11Radio0 (Wi-Fi 802.11)',
            shortName: 'Wlan0',
            macAddress: generateMacAddress(index + 50, 3),
            ipAddress: '192.168.10.1',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
            isWireless: true,
            natRole: 'inside' as const,
            bandwidthMbps: 300,
          },
        ]
      : effectiveModel === 'laptop' || effectiveModel === 'smartphone'
      ? [
          {
            id: `${id}-wlan0`,
            name: 'Wireless LAN 802.11',
            shortName: 'Wlan0',
            macAddress: generateMacAddress(index + 60, 1),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1],
            isWireless: true,
            dhcpEnabled: true,
            bandwidthMbps: 300,
          },
        ]
      : effectiveModel === 'isp_cloud'
      ? [
          {
            id: `${id}-gi0/0`,
            name: 'GigabitEthernet0/0 (eBGP Customer Edge Uplink)',
            shortName: 'Gi0/0',
            macAddress: generateMacAddress(index + 85, 1),
            ipAddress: '203.0.113.1',
            subnetMask: '255.255.255.252',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1],
            natRole: 'inside' as const,
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-gi0/1`,
            name: 'GigabitEthernet0/1 (IXP / Global Internet Core)',
            shortName: 'Gi0/1',
            macAddress: generateMacAddress(index + 85, 2),
            ipAddress: '8.8.8.1',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1],
            natRole: 'outside' as const,
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-gi0/2`,
            name: 'GigabitEthernet0/2 (eBGP Transit Peer)',
            shortName: 'Gi0/2',
            macAddress: generateMacAddress(index + 85, 3),
            ipAddress: '198.51.100.1',
            subnetMask: '255.255.255.252',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1],
            natRole: 'inside' as const,
            bandwidthMbps: 1000,
          },
        ]
      : type === 'router'
      ? [
          {
            id: `${id}-fa0/0`,
            name: 'FastEthernet0/0',
            shortName: 'Fa0/0',
            macAddress: generateMacAddress(index, 1),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
          },
          {
            id: `${id}-fa0/1`,
            name: 'FastEthernet0/1',
            shortName: 'Fa0/1',
            macAddress: generateMacAddress(index, 2),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
          },
          {
            id: `${id}-gi0/0`,
            name: 'GigabitEthernet0/0',
            shortName: 'Gi0/0',
            macAddress: generateMacAddress(index, 3),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
          },
        ]
      : effectiveModel === 'gpon_olt'
      ? [
          ...Array.from({ length: 4 }, (_, i) => {
            const ponNum = i + 1;
            return {
              id: `${id}-pon0/${ponNum}`,
              name: `GPON 0/${ponNum} (1490nm TX / 1310nm RX · 2.5G/1.25G)`,
              shortName: `PON0/${ponNum}`,
              macAddress: generateMacAddress(index + 110, ponNum),
              ipAddress: '',
              subnetMask: '',
              adminStatus: 'up' as const,
              vlanMode: 'trunk' as const,
              accessVlan: 100,
              trunkAllowedVlans: [1, 10, 20, 30, 100, 200, 300],
              bandwidthMbps: 2500,
            };
          }),
          {
            id: `${id}-gi0/1`,
            name: 'GigabitEthernet0/1 (10G SFP+ Uplink Trunk)',
            shortName: 'Gi0/1',
            macAddress: generateMacAddress(index + 110, 5),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 100,
            trunkAllowedVlans: [1, 10, 20, 30, 100, 200, 300],
            bandwidthMbps: 10000,
          },
          {
            id: `${id}-gi0/2`,
            name: 'GigabitEthernet0/2 (10G SFP+ Uplink Trunk)',
            shortName: 'Gi0/2',
            macAddress: generateMacAddress(index + 110, 6),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 100,
            trunkAllowedVlans: [1, 10, 20, 30, 100, 200, 300],
            bandwidthMbps: 10000,
          },
        ]
      : effectiveModel === 'gpon_ont'
      ? [
          {
            id: `${id}-pon0`,
            name: 'PON0 Optical SC/APC (1490nm RX / 1310nm TX)',
            shortName: 'PON0',
            macAddress: generateMacAddress(index + 120, 1),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 100,
            trunkAllowedVlans: [1, 10, 20, 30, 100, 200, 300],
            bandwidthMbps: 2500,
          },
          {
            id: `${id}-lan1`,
            name: 'LAN1 (Порт 1 — Интернет PPPoE / DHCP · VLAN 100)',
            shortName: 'LAN1',
            macAddress: generateMacAddress(index + 120, 2),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 100,
            trunkAllowedVlans: [100],
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-lan2`,
            name: 'LAN2 (Порт 2 — IPTV Multicast IGMP · VLAN 200)',
            shortName: 'LAN2',
            macAddress: generateMacAddress(index + 120, 3),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 200,
            trunkAllowedVlans: [200],
            bandwidthMbps: 1000,
          },
          {
            id: `${id}-lan3`,
            name: 'LAN3 / FXS (Порт 3 — VoIP Телефония SIP · VLAN 300)',
            shortName: 'LAN3',
            macAddress: generateMacAddress(index + 120, 4),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 300,
            voiceVlan: 300,
            poeEnabled: true,
            trunkAllowedVlans: [300],
            bandwidthMbps: 100,
          },
        ]
      : type === 'switch'
      ? [
          ...Array.from({ length: cleanSwitchPorts }, (_, i) => {
            const portNum = i + 1;
            return {
              id: `${id}-fa0/${portNum}`,
              name: `FastEthernet0/${portNum}`,
              shortName: `Fa0/${portNum}`,
              macAddress: generateMacAddress(index, portNum),
              ipAddress: '',
              subnetMask: '',
              adminStatus: 'up' as const,
              vlanMode: 'access' as const,
              accessVlan: 1,
              trunkAllowedVlans: [1, 10, 20, 30],
            };
          }),
          {
            id: `${id}-gi0/1`,
            name: 'GigabitEthernet0/1',
            shortName: 'Gi0/1',
            macAddress: generateMacAddress(index, cleanSwitchPorts + 1),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
          },
          {
            id: `${id}-gi0/2`,
            name: 'GigabitEthernet0/2',
            shortName: 'Gi0/2',
            macAddress: generateMacAddress(index, cleanSwitchPorts + 2),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'trunk' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1, 10, 20, 30],
          },
        ]
      : effectiveModel === 'ip_phone'
      ? [
          {
            id: `${id}-sw`,
            name: 'Switch Port 10/100 (PoE 802.3af + Voice/Data VLAN)',
            shortName: 'SW',
            macAddress: generateMacAddress(index + 90, 1),
            ipAddress: `192.168.20.${10 + index}`,
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 20,
            trunkAllowedVlans: [10, 20],
            bandwidthMbps: 100,
          },
          {
            id: `${id}-pc`,
            name: 'PC Passthrough Port 10/100 (Data VLAN)',
            shortName: 'PC',
            macAddress: generateMacAddress(index + 90, 2),
            ipAddress: '',
            subnetMask: '',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 10,
            trunkAllowedVlans: [10],
            bandwidthMbps: 100,
          },
        ]
      : effectiveModel === 'ip_camera'
      ? [
          {
            id: `${id}-eth0`,
            name: 'FastEthernet0 (PoE 802.3af/at + CCTV VLAN 30)',
            shortName: 'Eth0',
            macAddress: generateMacAddress(index + 95, 1),
            ipAddress: `192.168.30.${10 + index}`,
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 30,
            trunkAllowedVlans: [30],
            bandwidthMbps: 100,
          },
        ]
      : effectiveModel === 'nvr'
      ? [
          {
            id: `${id}-eth0`,
            name: 'GigabitEthernet0 (NVR Storage Engine · VLAN 30)',
            shortName: 'Eth0',
            macAddress: generateMacAddress(index + 98, 1),
            ipAddress: '192.168.30.100',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 30,
            trunkAllowedVlans: [30],
            bandwidthMbps: 1000,
          },
        ]
      : [
          {
            id: `${id}-eth0`,
            name: 'Ethernet0',
            shortName: 'Eth0',
            macAddress: generateMacAddress(index, 1),
            ipAddress: '',
            subnetMask: '255.255.255.0',
            adminStatus: 'up' as const,
            vlanMode: 'access' as const,
            accessVlan: 1,
            trunkAllowedVlans: [1],
          },
        ];

  const defaultServices = createDefaultServices(type);
  if (effectiveModel === 'nvr') {
    defaultServices.nvrEnabled = true;
    defaultServices.nvrStorageTb = 16;
    defaultServices.nvrRetentionDays = 30;
    defaultServices.nvrMulticastGroup = '239.0.30.1';
    defaultServices.httpTitle = 'NetPulse NVR Surveillance & VMS Console (HTTP/1.1 200 OK)';
    defaultServices.httpBody =
      'Видеорегистратор NVR активен (RAID-6 16 TB). RTSP-сервер принимает потоки H.265/H.264 на TCP 554 / RTP UDP 5004 и Multicast 239.0.30.1.';
  }
  if (effectiveModel === 'soho_wifi_router') {
    defaultServices.dhcpEnabled = true;
    defaultServices.dhcpPools = [
      {
        id: `${id}-wlan-pool`,
        poolName: 'SOHO_WLAN_POOL',
        network: '192.168.10.0',
        mask: '255.255.255.0',
        defaultRouter: '192.168.10.1',
        dnsServer: '192.168.2.100',
        startIp: '192.168.10.50',
        endIp: '192.168.10.150',
      },
    ];
  }

  const baseNode: NetworkNode = {
    id,
    name,
    type,
    deviceModel: effectiveModel,
    x,
    y,
    defaultGateway: '',
    dnsServer: '192.168.2.100',
    ipAssignmentMode:
      effectiveModel === 'laptop' || effectiveModel === 'smartphone' ? 'dhcp' : 'static',
    natEnabled:
      effectiveModel === 'soho_wifi_router' ||
      effectiveModel === 'firewall' ||
      effectiveModel === 'isp_cloud'
        ? true
        : undefined,
    bgpConfig:
      effectiveModel === 'isp_cloud'
        ? getDefaultBgpConfig(index, true)
        : undefined,
    wanImpairment:
      effectiveModel === 'isp_cloud'
        ? getDefaultWanImpairmentConfig('primary')
        : undefined,
    firewallConfig:
      effectiveModel === 'firewall' ? getDefaultFirewallConfig(id) : undefined,
    wlcConfig:
      effectiveModel === 'wlc'
        ? {
            enabled: true,
            controllerName: name,
            managementIp: '192.168.10.5',
            managementVlan: 10,
            capwapUdpControlPort: 5246,
            capwapUdpDataPort: 5247,
            rfAutoChannel: true,
            defaultCoverageRadius: 245,
            wlanProfiles: [
              {
                id: `${id}-wlan-1`,
                wlanId: 1,
                profileName: 'Corp_Enterprise_WLAN',
                ssid: 'Corp-Enterprise',
                vlanId: 10,
                security: 'wpa2',
                password: 'cisco123',
                band: '2.4GHz',
                enabled: true,
              },
            ],
          }
        : undefined,
    wifiConfig:
      effectiveModel === 'wifi_ap'
        ? {
            enabled: true,
            ssid: 'Corp-WiFi',
            channel: 6,
            band: '2.4GHz',
            security: 'wpa2',
            password: 'cisco123',
            coverageRadius: 230,
            bridgeVlan: 1,
            apMode: 'autonomous',
            capwapStatus: 'standalone',
          }
        : effectiveModel === 'soho_wifi_router'
        ? {
            enabled: true,
            ssid: 'Home-WiFi-5G',
            channel: 36,
            band: '5GHz',
            security: 'wpa2',
            password: 'cisco123',
            coverageRadius: 240,
            bridgeVlan: 1,
            apMode: 'autonomous',
            capwapStatus: 'standalone',
          }
        : undefined,
    wifiClientConfig:
      effectiveModel === 'laptop' || effectiveModel === 'smartphone'
        ? {
            enabled: true,
            connectedSsid: 'Corp-WiFi',
            security: 'wpa2',
            passphrase: 'cisco123',
            autoRoaming: true,
          }
        : undefined,
    voipConfig:
      effectiveModel === 'ip_phone' ? getDefaultVoipPhoneConfig(index) : undefined,
    ipCameraConfig:
      effectiveModel === 'ip_camera' ? getDefaultIpCameraConfig(index) : undefined,
    gponOltConfig:
      effectiveModel === 'gpon_olt' ? getDefaultGponOltConfig() : undefined,
    gponOntConfig:
      effectiveModel === 'gpon_ont'
        ? getDefaultGponOntConfig(index, generateDefaultGponSn(index))
        : undefined,
    vlanDatabase:
      effectiveModel === 'gpon_olt' || effectiveModel === 'gpon_ont'
        ? [
            { id: 1, name: 'default', subnetHint: 'Native / Management VLAN' },
            { id: 100, name: 'GPON_Internet_PPPoE', subnetHint: '100.64.100.0/24 · Интернет (PPPoE / DHCP)' },
            { id: 200, name: 'GPON_IPTV_Multicast', subnetHint: '10.200.0.0/24 · IPTV Multicast (IGMP)' },
            { id: 300, name: 'GPON_VoIP_SIP', subnetHint: '10.30.0.0/24 · VoIP Телефония (SIP / RTP)' },
          ]
        : undefined,
    poeConfig:
      type === 'switch' && (effectiveModel === 'switch' || effectiveModel === 'gpon_ont')
        ? getDefaultSwitchPoeConfig()
        : undefined,
    defaultGateway:
      effectiveModel === 'ip_phone'
        ? '192.168.20.1'
        : effectiveModel === 'ip_camera' || effectiveModel === 'nvr'
        ? '192.168.30.1'
        : '',
    services: defaultServices,
    interfaces,
    routingTable: [],
    arpTable: [],
    macTable: [],
    cli: {
      mode: 'user',
      history: [
        `Cisco IOS Software, NetPulse Simulation OS, Version 15.4(3)M, RELEASE SOFTWARE`,
        `System image file is "flash:netpulse-advipservicesk9-mz.bin"`,
        `Введите "?" или "help" для справки по командам (включая ping, traceroute, ipconfig /renew).`,
      ],
    },
  };

  if (type === 'router') {
    baseNode.routingTable = syncConnectedRoutes(baseNode);
  }

  return baseNode;
}

